// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        // Initial state: totalSupply = 0, owner has 0 tokens.
        // Mint 1 token to owner so burn can be called.
        c.mintToken(address(this), 1);
        // Now totalSupply should be 1, owner balance is 1.
        // Call burn(1) — in reference, totalSupply becomes 0; in bug, becomes 2.
        c.burn(1);
        // Assert that totalSupply is 0 (reference behavior). Bug would make it 2.
        assertTrue(c.totalSupply() == 0);
    }
}

