pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        address owner = address(this);
        // Step 1: owner freezes himself (sets frozenAccount[owner] = true in reference, or false in bug)
        c.freezeAccount(owner, true);
        // Step 2: owner calls burn(1) — onlyOwner modifier ensures owner is caller
        // In reference: frozenAccount[owner] = true after freeze, burn succeeds (check is bypassed? Actually _transfer not called; burn only checks balanceOf).
        // But we need to diverge in frozenAccount after the call — we must examine the state after burn.
        // Actually burn does not modify frozenAccount. So we need a different approach.
        // Instead, freeze some other account K, then after burn? No, burn only affects totalSupply and balanceOf[msg.sender].
        // The original difference says after burn the frozenAccount differs at some key k. But burn doesn't touch frozenAccount.
        // The mutant only changes freezeAccount. So to get divergence after burn, we need a call sequence: freezeAccount sets frozenAccount[k] to something, then burn happens, but burn doesn't affect frozenAccount. The divergence must be that the frozenAccount call itself is wrong: after freezeAccount(target, freeze), the reference sets true when freeze=true, bug sets false. So we just call freezeAccount and check frozenAccount getter.
        // The problem says "after a call to burn(...) completes" — maybe because the test scenario includes a burn before checking? But burn doesn't change frozenAccount. So the only way is: set up via freezeAccount, then burn (which doesn't change), then check frozenAccount getter. The divergence comes from the freezeAccount call, not burn.
        // So we call freezeAccount(owner, true) first. Then call burn(1) (to satisfy "after burn" condition). Then check frozenAccount[owner]. Reference: true, bug: false.
        c.burn(1);
        bool frozen = c.frozenAccount(owner);
        assertTrue(frozen == true);
    }
}

