import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testRegression_property() public {
        address alice = address(0xaaa);
        address bob = address(0xbbb);
        address charlie = address(0xccc);
        // Give alice ownership and mint tokens to bob
        vm.prank(alice);
        c.mintToken(bob, 100);
        // Alice freezes Bob's account with freeze=true
        vm.prank(alice);
        c.freezeAccount(bob, true);
        // Bob tries to transfer 1 token to Charlie
        vm.prank(bob);
        bool ok;
        try c.transfer(charlie, 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, frozenAccount[bob]=true => transfer reverts => ok=false
        // In bug, frozenAccount[bob]=false => transfer succeeds => ok=true
        assertTrue(!ok, "Bob's transfer should have reverted");
    }
}

