        vm.prank(address(this));
        c.mintToken(address(this), 1000);

        vm.prank(address(this));
        c.burn(100);

        // Reference: frozenAccount[owner] remains false.
        // Bug: frozenAccount[owner] becomes true after freezeAccount call, but here we call burn, not freezeAccount.
        // Actually the bug is in freezeAccount, but the divergence description says after a call to burn(...), frozenAccount differs.
        // That's impossible unless freezeAccount is called first. Wait, the mutant changes freezeAccount, not burn.
        // The description says: "Driven through the public/external entry `burn(uint256)`, P and M differ... after a call to `burn(...)` completes, the value of `frozenAccount` differs at some key k".
        // This cannot happen unless freezeAccount is called before burn. So we need to call freezeAccount first to trigger the bug.
        // Let's call freezeAccount(someAddress, false) so the bug sets frozenAccount[msg.sender] = true first.
        // Then call burn on that same msg.sender? Actually burn doesn't check frozenAccount. So the divergence is observed after burn.

        // Concrete scenario:
        // 1. Owner calls freezeAccount(address(0x123), false);
        //    Reference: frozenAccount[0x123] = false.
        //    Bug: first sets frozenAccount[owner] = true, then frozenAccount[0x123] = false.
        // 2. Owner calls burn(100) (no effect on frozenAccount but the test reads frozenAccount(owner) after).
        // Reference: frozenAccount(owner) = false; Bug: frozenAccount(owner) = true.

        vm.prank(address(this));
        c.freezeAccount(address(0x123), false);

        vm.prank(address(this));
        c.burn(100);

