        // nonOwner tries to transfer tokens to another address
        vm.prank(nonOwner);
        bool transferSucceeded;
        try c.transfer(address(0x456), 50) {
            transferSucceeded = true;
        } catch {
            transferSucceeded = false;
        }

        // After transfer attempt, check frozenAccount state
        bool frozenAfter = c.frozenAccount(nonOwner);

        // Assert: The reference contract (correct) does NOT revert on transfer (owner's onlyOwner not invoked),
        // so state unchanged. The buggy contract reverts before freezing, so state unchanged as well.
        // Key divergence: In reference, frozenAccount(nonOwner) stays false (unchanged).
        // In buggy version, the transfer reverts, so state unchanged as well.
        // Wait - we need a concrete difference. Let's refine:
        // The buggy contract's onlyOwner modifier always reverts - but transfer does NOT use onlyOwner!
        // So this scenario doesn't trigger the bug.
        // Correct scenario: owner calls burn() which uses onlyOwner.

        // Re-initialize: fresh contract, owner calls burn(0)
        c = new C(0, "", "");

        // Record frozenAccount before burn
        bool frozenBeforeBurn = c.frozenAccount(c.owner());

        vm.prank(c.owner());
        bool burnSucceeded;
        try c.burn(0) {
            burnSucceeded = true;
        } catch {
            burnSucceeded = false;
        }

        // After burn attempt, record frozenAccount
        bool frozenAfterBurn = c.frozenAccount(c.owner());

        // Reference: burn(0) succeeds (owner passes onlyOwner, balance 0 >= 0), frozenAccount unchanged
        // Buggy: burn(0) reverts due to require(false) in onlyOwner, frozenAccount unchanged
        // No divergence here either.

        // Let's use the exact difference: after burn, frozenAccount differs at some key.
        // We need a call that changes frozenAccount in one version but not the other.
        // The onlyOwner modifier controls freezeAccount. In reference, owner can freeze.
        // In buggy, freezeAccount always reverts.
        // So: owner calls freezeAccount(nonOwner, true). Reference succeeds, buggy reverts.

        // Reset
        c = new C(0, "", "");

        vm.prank(c.owner());
        bool freezeSucceeded;
        try c.freezeAccount(nonOwner, true) {
            freezeSucceeded = true;
        } catch {
            freezeSucceeded = false;
        }

        // Reference: freeze succeeded, so frozenAccount(nonOwner) == true
        // Buggy: freeze reverted, so frozenAccount(nonOwner) == false
        assertTrue(c.frozenAccount(nonOwner));
    }
